const weekStart = $input.first().json.query?.weekStart;
const date = new Date(typeof weekStart === 'string' ? weekStart + 'T00:00:00Z' : NaN);
const valid = typeof weekStart === 'string'
  && /^\d{4}-\d{2}-\d{2}$/.test(weekStart)
  && Number.isFinite(date.getTime())
  && date.toISOString().slice(0, 10) === weekStart
  && date.getUTCDay() === 1
  && date.getUTCFullYear() >= 2008
  && date.getUTCFullYear() <= 9998;
if (!valid) return [{ json: { valid } }];

const repository = 'nullifierx1/n8n-code-review-test';
const offset = (days) => new Date(date.getTime() + days * 86400000).toISOString().slice(0, 10);
return [{ json: {
  valid, weekStart, weekEnd: offset(6), weekEndExclusive: offset(7),
  currentKey: repository + '#' + weekStart,
  previousKey: repository + '#' + offset(-7),
} }];

const { currentKey, weekStart } = $('Validate week').first().json;
const rows = $input.all().map(({ json }) => json).filter((row) => Object.keys(row).length > 0);
if (rows.length > 1 || rows.some((row) => row.report_key !== currentKey)) {
  throw new Error('Invalid or duplicate selected row');
}
return [{ json: { weekStart, row: rows[0] ?? null } }];

const { weekStart, weekEnd, weekEndExclusive, previousKey } = $('Validate week').first().json;
const { row } = $('Select current row').first().json;
const previousRows = $input.all().map(({ json }) => json).filter((entry) => Object.keys(entry).length > 0);
if (previousRows.length > 1 || previousRows.some((entry) => entry.report_key !== previousKey)) {
  throw new Error('Invalid or duplicate previous row');
}
const isCount = (value) => Number.isSafeInteger(value) && value >= 0;
function countsFrom(entry) {
  const counts = {
    openedIssues: entry.issues_created,
    closedIssues: entry.issues_closed,
    openedPrs: entry.prs_created,
    mergedPrs: entry.prs_merged,
  };
  if (!Object.values(counts).every(isCount)) throw new Error('Invalid metric count');
  return counts;
}
function checkPeriod(entry, start, endExclusive) {
  if (Date.parse(entry.week_start) !== Date.parse(start + 'T00:00:00Z') ||
      Date.parse(entry.week_end) !== Date.parse(endExclusive + 'T00:00:00Z')) {
    throw new Error('Invalid saved report period');
  }
}
function parseBreakdowns(entry) {
  const types = JSON.parse(entry.by_type_json);
  const authors = JSON.parse(entry.by_author_json);
  const categories = ['bug', 'task', 'feature', 'unknown'];
  if (!types || typeof types !== 'object' || Array.isArray(types) ||
      Object.keys(types).length !== categories.length ||
      !categories.every((key) => isCount(types[key])) ||
      !Array.isArray(authors) || !authors.every((item) => item &&
        typeof item.author === 'string' && item.author.length && isCount(item.issues_created)) ||
      new Set(authors.map((item) => item.author)).size !== authors.length) {
    throw new Error('Invalid saved report breakdown');
  }
  return {
    byType: categories.map((label) => ({ label, count: types[label] })),
    byAuthor: authors.map(({ author, issues_created }) => ({ label: author, count: issues_created })),
  };
}

checkPeriod(row, weekStart, weekEndExclusive);
const counts = countsFrom(row);
const { byType, byAuthor } = parseBreakdowns(row);
const previous = previousRows[0];
let comparison = null;
if (previous) {
  checkPeriod(previous, previousKey.slice(-10), weekStart);
  const previousCounts = countsFrom(previous);
  parseBreakdowns(previous);
  comparison = Object.fromEntries(Object.entries(counts).map(([key, value]) => [key, value - previousCounts[key]]));
}
return [{ json: { status: 'success', weekStart, weekEnd, counts, byType, byAuthor, comparison } }];
